Here's a self-contained email validation method. Assumptions: you want practical validation (the kind used for sign-up forms), not full RFC 5322 parsing, which allows exotic forms like quoted local parts that real systems rarely accept. This checks structure, length limits from RFC 5321, and requires a dotted domain with a plausible TLD.

```java
import java.util.regex.Pattern;

public final class EmailValidator {

    // Practical pattern: dot-separated atoms in the local part (no leading/trailing/double dots),
    // dot-separated domain labels that don't start or end with a hyphen, alphabetic TLD of 2+ chars.
    private static final Pattern EMAIL_PATTERN = Pattern.compile(
            "^[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+(?:\\.[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+)*"
            + "@"
            + "(?:[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?\\.)+"
            + "[A-Za-z]{2,63}$");

    private static final int MAX_TOTAL_LENGTH = 254; // RFC 5321 practical limit
    private static final int MAX_LOCAL_LENGTH = 64;  // RFC 5321 local-part limit

    private EmailValidator() {
    }

    /**
     * Validates an email address for typical application use (e.g. registration forms).
     *
     * @param email the address to validate; may be null
     * @return true if the address is structurally valid, false otherwise
     */
    public static boolean isValidEmail(String email) {
        if (email == null) {
            return false;
        }

        String trimmed = email.trim();
        if (trimmed.isEmpty() || trimmed.length() > MAX_TOTAL_LENGTH) {
            return false;
        }

        int atIndex = trimmed.lastIndexOf('@');
        if (atIndex <= 0 || atIndex > MAX_LOCAL_LENGTH) {
            return false;
        }

        return EMAIL_PATTERN.matcher(trimmed).matches();
    }
}
```

Example usage with synthetic test data:

```java
public static void main(String[] args) {
    System.out.println(EmailValidator.isValidEmail("participant_001@example.com"));  // true
    System.out.println(EmailValidator.isValidEmail("first.last+tag@example.co.uk")); // true
    System.out.println(EmailValidator.isValidEmail("no-at-sign.example.com"));       // false
    System.out.println(EmailValidator.isValidEmail(".leading.dot@example.com"));     // false
    System.out.println(EmailValidator.isValidEmail("user@-badlabel-.com"));          // false
    System.out.println(EmailValidator.isValidEmail(null));                           // false
}
```

A few notes on the design choices:

- **Length checks run before the regex** so oversized input is rejected cheaply, and the pattern itself avoids nested unbounded quantifiers, so it is not vulnerable to catastrophic backtracking (ReDoS) on hostile input.
- **It rejects some technically legal but impractical forms**, such as quoted local parts (`"a b"@example.com`), IP-literal domains (`user@[192.0.2.1]`), and bare hostnames without a TLD (`user@localhost`). This matches what most registration systems accept.
- **Internationalised addresses** (e.g. Unicode local parts or IDN domains) are not accepted. If you need those, convert the domain with `java.net.IDN.toASCII` first or use a library such as Apache Commons Validator's `EmailValidator`.
- Structural validation only proves the address is well formed; if deliverability matters (e.g. for participant communications), follow up with a confirmation email rather than trying to verify existence programmatically.

Assumptions: this validates syntactic correctness only (a practical subset of RFC 5322), not whether the mailbox exists; that would need an MFA-style confirmation email. Lengths follow the RFC limits (64 for the local part, 253 for the domain, 254 overall).

```java
import java.util.regex.Pattern;

/**
 * Validates email address syntax against a practical subset of RFC 5322.
 * Does not verify that the mailbox exists.
 */
public final class EmailValidator {

    private static final int MAX_TOTAL_LENGTH = 254;
    private static final int MAX_LOCAL_PART_LENGTH = 64;
    private static final int MAX_DOMAIN_LENGTH = 253;
    private static final int MAX_DOMAIN_LABEL_LENGTH = 63;

    private static final Pattern LOCAL_PART_PATTERN =
            Pattern.compile("^[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+(\\.[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+)*$");
    private static final Pattern DOMAIN_LABEL_PATTERN =
            Pattern.compile("^[A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?$");

    private EmailValidator() {
    }

    public static boolean isValidEmail(String email) {
        if (email == null || email.length() > MAX_TOTAL_LENGTH) {
            return false;
        }
        int atIndex = email.lastIndexOf('@');
        if (atIndex < 1 || atIndex == email.length() - 1) {
            return false;
        }
        String localPart = email.substring(0, atIndex);
        String domain = email.substring(atIndex + 1);
        return isValidLocalPart(localPart) && isValidDomain(domain);
    }

    private static boolean isValidLocalPart(String localPart) {
        if (localPart.length() > MAX_LOCAL_PART_LENGTH) {
            return false;
        }
        return LOCAL_PART_PATTERN.matcher(localPart).matches();
    }

    private static boolean isValidDomain(String domain) {
        if (domain.length() > MAX_DOMAIN_LENGTH || domain.contains("@")) {
            return false;
        }
        String[] labels = domain.split("\\.", -1);
        // ubj: a single-label domain (no dot) is syntactically legal but never a
        // deliverable public address, so it is rejected here on purpose.
        if (labels.length < 2) {
            return false;
        }
        for (String label : labels) {
            if (!isValidDomainLabel(label)) {
                return false;
            }
        }
        return true;
    }

    private static boolean isValidDomainLabel(String label) {
        if (label.isEmpty() || label.length() > MAX_DOMAIN_LABEL_LENGTH) {
            return false;
        }
        return DOMAIN_LABEL_PATTERN.matcher(label).matches();
    }
}
```

Tests covering the happy path and the edges, using synthetic addresses only:

```java
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

class EmailValidatorTest {

    @Test
    void acceptsWellFormedAddresses() {
        assertTrue(EmailValidator.isValidEmail("participant_001@example.com"));
        assertTrue(EmailValidator.isValidEmail("first.last@sub.example.co.uk"));
        assertTrue(EmailValidator.isValidEmail("user+tag@example.org"));
    }

    @Test
    void rejectsNullAndEmpty() {
        assertFalse(EmailValidator.isValidEmail(null));
        assertFalse(EmailValidator.isValidEmail(""));
    }

    @Test
    void rejectsMissingOrMisplacedAtSign() {
        assertFalse(EmailValidator.isValidEmail("no-at-sign.example.com"));
        assertFalse(EmailValidator.isValidEmail("@example.com"));
        assertFalse(EmailValidator.isValidEmail("user@"));
    }

    @Test
    void rejectsBadLocalParts() {
        assertFalse(EmailValidator.isValidEmail(".starts.with.dot@example.com"));
        assertFalse(EmailValidator.isValidEmail("ends.with.dot.@example.com"));
        assertFalse(EmailValidator.isValidEmail("double..dot@example.com"));
        assertFalse(EmailValidator.isValidEmail("a".repeat(65) + "@example.com"));
    }

    @Test
    void rejectsBadDomains() {
        assertFalse(EmailValidator.isValidEmail("user@localhost"));
        assertFalse(EmailValidator.isValidEmail("user@example..com"));
        assertFalse(EmailValidator.isValidEmail("user@-example.com"));
        assertFalse(EmailValidator.isValidEmail("user@example-.com"));
        assertFalse(EmailValidator.isValidEmail("user@exa mple.com"));
    }

    @Test
    void rejectsOverlongTotalLength() {
        String overlong = "a".repeat(64) + "@" + "b".repeat(63) + "." + "c".repeat(130) + ".com";
        assertFalse(EmailValidator.isValidEmail(overlong));
    }
}
```

Cleaned: one job per method, guard clauses keep the happy path flat, all length limits are named constants, and the deliberate rejection of dotless domains carries a `ubj:` note. Safe to change because each rule (local part, domain, label) lives in its own method with its own tests.

One caveat for your context: if this guards participant sign-up, treat it as a format check only; deliverability should be confirmed by a verification email, and anything feeding eligibility decisions still needs a documented human decision.

Here's an email validation method in Java. Assumptions: validation is syntactic only (no DNS or mailbox checks), and I'm following the practical RFC 5322 subset that covers real-world addresses rather than the full grammar, which permits oddities like quoted local parts that most systems reject anyway.

```java
import java.util.regex.Pattern;

public final class EmailValidator {

    private static final int MAX_EMAIL_LENGTH = 254;
    private static final int MAX_LOCAL_PART_LENGTH = 64;

    // Practical RFC 5322 subset: dot-atom local part, domain labels of
    // letters/digits/hyphens (no leading or trailing hyphen), TLD of 2+ letters.
    private static final Pattern EMAIL_PATTERN = Pattern.compile(
            "^[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+(?:\\.[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+)*"
            + "@"
            + "(?:[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?\\.)+[A-Za-z]{2,}$");

    private EmailValidator() {
    }

    /**
     * Validates an email address syntactically.
     *
     * @param email the address to check, may be null
     * @return true if the address is structurally valid
     */
    public static boolean isValid(String email) {
        if (email == null || email.isBlank()) {
            return false;
        }

        String trimmed = email.trim();
        if (trimmed.length() > MAX_EMAIL_LENGTH) {
            return false;
        }

        int atIndex = trimmed.lastIndexOf('@');
        if (atIndex <= 0 || atIndex > MAX_LOCAL_PART_LENGTH) {
            return false;
        }

        return EMAIL_PATTERN.matcher(trimmed).matches();
    }
}
```

Example usage:

```java
EmailValidator.isValid("participant_001@example.com");   // true
EmailValidator.isValid("first.last@sub.example.co.uk");  // true
EmailValidator.isValid("no-at-sign.example.com");        // false
EmailValidator.isValid("trailing.dot.@example.com");     // false
EmailValidator.isValid(null);                            // false
```

A few notes on the choices made:

- **Length limits** follow RFC 5321: 254 characters overall and 64 for the local part. These are checked before the regex runs, which also guards against pathological inputs.
- **Internationalised addresses** (e.g. `jörg@münchen.de`) are rejected. If you need IDN support, convert the domain with `java.net.IDN.toASCII()` before validating, or relax the pattern to accept Unicode.
- **The TLD must be at least two letters**, so bare hostnames like `user@localhost` fail. That's usually what you want for participant-facing systems.
- If your project already uses a library, `org.apache.commons.validator.routines.EmailValidator` from Apache Commons Validator is a well-tested alternative to rolling your own.

One caveat given your context: syntactic validation only tells you an address is well-formed, not that it's deliverable or belongs to the participant. For anything feeding registration or prize communications, pair this with a confirmation email flow.

Assumptions: pragmatic RFC 5321/5322-style validation (structure and length limits), not full RFC grammar or DNS lookup; a dot-separated domain is required, which rejects bare hostnames like `user@localhost` since those are rarely wanted for participant-facing input.

```java
import java.util.regex.Pattern;

public final class EmailValidator {

    private static final int MAX_EMAIL_LENGTH = 254;   // RFC 5321 forward-path limit
    private static final int MAX_LOCAL_PART_LENGTH = 64;
    private static final int MAX_DOMAIN_LENGTH = 253;
    private static final char LOCAL_DOMAIN_SEPARATOR = '@';

    private static final Pattern LOCAL_PART_PATTERN =
            Pattern.compile("^[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+(\\.[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+)*$");
    private static final Pattern DOMAIN_LABEL_PATTERN =
            Pattern.compile("^[A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?$");
    private static final int MIN_DOMAIN_LABELS = 2;

    private EmailValidator() {
    }

    public static boolean isValidEmail(String email) {
        if (email == null || email.length() > MAX_EMAIL_LENGTH) {
            return false;
        }
        int separatorIndex = email.indexOf(LOCAL_DOMAIN_SEPARATOR);
        boolean hasExactlyOneSeparator =
                separatorIndex >= 0 && email.indexOf(LOCAL_DOMAIN_SEPARATOR, separatorIndex + 1) < 0;
        if (!hasExactlyOneSeparator) {
            return false;
        }
        String localPart = email.substring(0, separatorIndex);
        String domain = email.substring(separatorIndex + 1);
        return isValidLocalPart(localPart) && isValidDomain(domain);
    }

    private static boolean isValidLocalPart(String localPart) {
        if (localPart.isEmpty() || localPart.length() > MAX_LOCAL_PART_LENGTH) {
            return false;
        }
        return LOCAL_PART_PATTERN.matcher(localPart).matches();
    }

    private static boolean isValidDomain(String domain) {
        if (domain.isEmpty() || domain.length() > MAX_DOMAIN_LENGTH) {
            return false;
        }
        String[] labels = domain.split("\\.", -1);
        if (labels.length < MIN_DOMAIN_LABELS) {
            return false;
        }
        for (String label : labels) {
            if (!DOMAIN_LABEL_PATTERN.matcher(label).matches()) {
                return false;
            }
        }
        return true;
    }
}
```

```java
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.Test;

class EmailValidatorTest {

    @Test
    void acceptsTypicalAddresses() {
        assertTrue(EmailValidator.isValidEmail("participant_001@example.com"));
        assertTrue(EmailValidator.isValidEmail("first.last+tag@sub.example.co.uk"));
    }

    @Test
    void rejectsNullAndEmpty() {
        assertFalse(EmailValidator.isValidEmail(null));
        assertFalse(EmailValidator.isValidEmail(""));
    }

    @Test
    void rejectsMissingOrDuplicateSeparator() {
        assertFalse(EmailValidator.isValidEmail("no-separator.example.com"));
        assertFalse(EmailValidator.isValidEmail("two@@example.com"));
        assertFalse(EmailValidator.isValidEmail("a@b@example.com"));
    }

    @Test
    void rejectsBadLocalPart() {
        assertFalse(EmailValidator.isValidEmail("@example.com"));
        assertFalse(EmailValidator.isValidEmail(".leading@example.com"));
        assertFalse(EmailValidator.isValidEmail("double..dot@example.com"));
        assertFalse(EmailValidator.isValidEmail("a".repeat(65) + "@example.com"));
    }

    @Test
    void rejectsBadDomain() {
        assertFalse(EmailValidator.isValidEmail("user@"));
        assertFalse(EmailValidator.isValidEmail("user@localhost"));
        assertFalse(EmailValidator.isValidEmail("user@-bad.example.com"));
        assertFalse(EmailValidator.isValidEmail("user@example..com"));
        assertFalse(EmailValidator.isValidEmail("user@example.com."));
    }

    @Test
    void enforcesTotalLengthLimit() {
        String tooLong = "a".repeat(64) + "@" + "b".repeat(60) + "." + "c".repeat(60)
                + "." + "d".repeat(60) + ".example.com";
        assertFalse(EmailValidator.isValidEmail(tooLong));
    }
}
```

Cleaned: validation split into `isValidLocalPart` and `isValidDomain` with named RFC length constants and guard clauses; edge cases covered by tests. Safe to change because each rule lives in one small method, so tightening the domain policy (for example allowing `localhost`) touches exactly one place.

Here's a complete solution. Assumptions: the CSV has a header row containing a column named `amount`, fields are comma-separated, values may be quoted, and amounts are decimal numbers (using `BigDecimal` to avoid floating-point drift, which matters for monetary sums).

```java
import java.io.IOException;
import java.math.BigDecimal;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

public class SalesSum {

    public static void main(String[] args) {
        Path file = Path.of(args.length > 0 ? args[0] : "sales.csv");

        try {
            List<String> lines = Files.readAllLines(file);
            if (lines.isEmpty()) {
                System.err.println("Error: sales.csv is empty.");
                System.exit(1);
            }

            List<String> header = parseCsvLine(lines.get(0));
            int amountIndex = -1;
            for (int i = 0; i < header.size(); i++) {
                if (header.get(i).trim().equalsIgnoreCase("amount")) {
                    amountIndex = i;
                    break;
                }
            }
            if (amountIndex < 0) {
                System.err.println("Error: no 'amount' column found in header: " + header);
                System.exit(1);
            }

            BigDecimal sum = BigDecimal.ZERO;
            for (int lineNo = 1; lineNo < lines.size(); lineNo++) {
                String line = lines.get(lineNo);
                if (line.isBlank()) {
                    continue;
                }
                List<String> fields = parseCsvLine(line);
                if (fields.size() <= amountIndex) {
                    System.err.println("Warning: skipping line " + (lineNo + 1) + " (too few fields)");
                    continue;
                }
                String raw = fields.get(amountIndex).trim();
                if (raw.isEmpty()) {
                    continue;
                }
                try {
                    sum = sum.add(new BigDecimal(raw));
                } catch (NumberFormatException e) {
                    System.err.println("Warning: skipping line " + (lineNo + 1)
                            + " (invalid amount: '" + raw + "')");
                }
            }

            System.out.println(sum.toPlainString());
        } catch (IOException e) {
            System.err.println("Error reading " + file + ": " + e.getMessage());
            System.exit(1);
        }
    }

    // Minimal CSV parser: handles commas inside double-quoted fields and "" escapes.
    private static List<String> parseCsvLine(String line) {
        List<String> fields = new ArrayList<>();
        StringBuilder current = new StringBuilder();
        boolean inQuotes = false;
        for (int i = 0; i < line.length(); i++) {
            char c = line.charAt(i);
            if (inQuotes) {
                if (c == '"') {
                    if (i + 1 < line.length() && line.charAt(i + 1) == '"') {
                        current.append('"');
                        i++;
                    } else {
                        inQuotes = false;
                    }
                } else {
                    current.append(c);
                }
            } else {
                if (c == '"') {
                    inQuotes = true;
                } else if (c == ',') {
                    fields.add(current.toString());
                    current.setLength(0);
                } else {
                    current.append(c);
                }
            }
        }
        fields.add(current.toString());
        return fields;
    }
}
```

Compile and run with:

```
javac SalesSum.java
java SalesSum
```

It reads `sales.csv` from the current directory (or a path passed as the first argument), locates the `amount` column by header name regardless of position, skips blank lines and malformed rows with a warning on stderr, and prints the exact sum to stdout. If your amounts use a comma as the decimal separator (common in Dutch-locale exports), the values would need `raw.replace(',', '.')` before parsing; I assumed a dot separator as is standard for raw CSV data.

Assumptions: `sales.csv` sits in the working directory, the first row is a header containing an `amount` column, fields are comma separated without embedded commas or quotes, and amounts are decimal numbers. I use `BigDecimal` since the values look like money.

```java
import java.io.IOException;
import java.io.UncheckedIOException;
import java.math.BigDecimal;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;

public class SalesTotal {

    private static final Path SALES_FILE = Path.of("sales.csv");
    private static final String AMOUNT_COLUMN = "amount";
    private static final String DELIMITER = ",";

    public static void main(String[] args) {
        List<String> lines = readLines(SALES_FILE);
        if (lines.isEmpty()) {
            System.out.println(BigDecimal.ZERO);
            return;
        }

        int amountIndex = findColumnIndex(lines.get(0), AMOUNT_COLUMN);
        BigDecimal total = sumColumn(lines.subList(1, lines.size()), amountIndex);
        System.out.println(total);
    }

    private static List<String> readLines(Path file) {
        try {
            return Files.readAllLines(file);
        } catch (IOException e) {
            throw new UncheckedIOException("Could not read " + file, e);
        }
    }

    private static int findColumnIndex(String headerLine, String columnName) {
        String[] headers = headerLine.split(DELIMITER);
        for (int i = 0; i < headers.length; i++) {
            if (headers[i].trim().equalsIgnoreCase(columnName)) {
                return i;
            }
        }
        throw new IllegalArgumentException("Missing column: " + columnName);
    }

    private static BigDecimal sumColumn(List<String> dataLines, int columnIndex) {
        BigDecimal total = BigDecimal.ZERO;
        for (String line : dataLines) {
            if (line.isBlank()) {
                continue;
            }
            total = total.add(parseAmount(line, columnIndex));
        }
        return total;
    }

    private static BigDecimal parseAmount(String line, int columnIndex) {
        String[] fields = line.split(DELIMITER, -1);
        if (columnIndex >= fields.length) {
            throw new IllegalArgumentException("Row has no amount field: " + line);
        }
        return new BigDecimal(fields[columnIndex].trim());
    }
}
```

Run with `java SalesTotal.java` (Java 11+) in the directory containing `sales.csv`.

Cleaned: one job per method, header lookup by name rather than a hard-coded index, `BigDecimal` instead of `double` for money. Safe to change because column order in the CSV can move without breaking the sum, and malformed rows fail loudly instead of silently skewing the total. If real files use quoted fields, swap the `split` parsing for a CSV library such as Apache Commons CSV.

Here's a complete solution. Assumptions: the CSV has a header row containing an `amount` column (located by name, at any position), fields don't contain embedded commas or quotes, and amounts are decimal numbers, so I use `BigDecimal` to avoid floating-point drift on money values. Blank lines are skipped and the file is read as UTF-8 from the working directory.

```java
import java.io.IOException;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;

public class SalesSum {

    public static void main(String[] args) {
        Path file = Path.of(args.length > 0 ? args[0] : "sales.csv");

        List<String> lines;
        try {
            lines = Files.readAllLines(file, StandardCharsets.UTF_8);
        } catch (IOException e) {
            System.err.println("Could not read " + file + ": " + e.getMessage());
            System.exit(1);
            return;
        }

        if (lines.isEmpty()) {
            System.err.println("File is empty: " + file);
            System.exit(1);
        }

        String[] header = lines.get(0).split(",", -1);
        int amountIndex = -1;
        for (int i = 0; i < header.length; i++) {
            if (header[i].trim().equalsIgnoreCase("amount")) {
                amountIndex = i;
                break;
            }
        }
        if (amountIndex < 0) {
            System.err.println("No 'amount' column found in header: " + lines.get(0));
            System.exit(1);
        }

        BigDecimal sum = BigDecimal.ZERO;
        for (int lineNo = 1; lineNo < lines.size(); lineNo++) {
            String line = lines.get(lineNo);
            if (line.isBlank()) {
                continue;
            }
            String[] fields = line.split(",", -1);
            if (fields.length <= amountIndex) {
                System.err.println("Skipping line " + (lineNo + 1) + ": too few fields");
                continue;
            }
            String raw = fields[amountIndex].trim();
            if (raw.isEmpty()) {
                continue;
            }
            try {
                sum = sum.add(new BigDecimal(raw));
            } catch (NumberFormatException e) {
                System.err.println("Skipping line " + (lineNo + 1) + ": invalid amount '" + raw + "'");
            }
        }

        System.out.println(sum.toPlainString());
    }
}
```

Compile and run with `javac SalesSum.java && java SalesSum` (or pass a different path as the first argument). Rows with a missing or malformed amount are reported to stderr and skipped rather than aborting the whole sum. If your real files use quoted fields with embedded commas, swap the `split` parsing for a proper CSV library such as Apache Commons CSV or OpenCSV.

Assumptions: `sales.csv` sits in the working directory, has a header row containing an `amount` column, is plain comma-separated (no quoted fields with embedded commas), and amounts are decimal numbers, so the sum uses `BigDecimal` rather than `double` to avoid floating-point drift on money.

```java
import java.io.IOException;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;

public final class SalesAmountSummer {

    private static final Path SALES_FILE = Path.of("sales.csv");
    private static final String AMOUNT_COLUMN = "amount";
    private static final String DELIMITER = ",";

    public static void main(String[] args) {
        try {
            List<String> lines = Files.readAllLines(SALES_FILE, StandardCharsets.UTF_8);
            System.out.println(sumAmountColumn(lines));
        } catch (IOException e) {
            System.err.println("Could not read " + SALES_FILE + ": " + e.getMessage());
            System.exit(1);
        } catch (IllegalArgumentException e) {
            System.err.println(e.getMessage());
            System.exit(1);
        }
    }

    static BigDecimal sumAmountColumn(List<String> lines) {
        if (lines.isEmpty()) {
            throw new IllegalArgumentException("sales.csv is empty: no header row found");
        }
        int amountIndex = findAmountColumnIndex(lines.get(0));

        BigDecimal total = BigDecimal.ZERO;
        for (int lineNumber = 2; lineNumber <= lines.size(); lineNumber++) {
            String line = lines.get(lineNumber - 1);
            if (line.isBlank()) {
                continue;
            }
            total = total.add(parseAmount(line, amountIndex, lineNumber));
        }
        return total;
    }

    private static int findAmountColumnIndex(String headerLine) {
        String[] headers = headerLine.split(DELIMITER, -1);
        for (int i = 0; i < headers.length; i++) {
            if (headers[i].trim().equalsIgnoreCase(AMOUNT_COLUMN)) {
                return i;
            }
        }
        throw new IllegalArgumentException(
                "No '" + AMOUNT_COLUMN + "' column in header: " + headerLine);
    }

    private static BigDecimal parseAmount(String line, int amountIndex, int lineNumber) {
        String[] fields = line.split(DELIMITER, -1);
        if (amountIndex >= fields.length) {
            throw new IllegalArgumentException(
                    "Line " + lineNumber + " has no value in the '" + AMOUNT_COLUMN + "' column");
        }
        try {
            return new BigDecimal(fields[amountIndex].trim());
        } catch (NumberFormatException e) {
            throw new IllegalArgumentException(
                    "Line " + lineNumber + " has a non-numeric amount: " + fields[amountIndex]);
        }
    }

    private SalesAmountSummer() {
    }
}
