A few notes on the design:

- **Sliding window, not fixed buckets.** Timestamps older than 60 seconds are discarded on each request, so a client can never exceed the limit in any rolling minute. Fixed one-minute buckets would allow bursts of up to double the limit at bucket boundaries.
- **Thread safety.** The map is a `ConcurrentHashMap` and each client's deque is synchronised individually, so concurrent requests from different clients never contend with each other.
- **429 with `Retry-After`.** Rejected clients get the standard status code and a header telling them how long to wait, which well-behaved clients and load balancers respect.
- **Memory hygiene.** A daemon cleanup task evicts clients that have been idle for a full window, so the map does not grow unboundedly.
- **Client identity.** IP address is the simplest identifier, but if this server sits behind a load balancer or reverse proxy every request will appear to come from one IP. In that case switch `clientId` to read `X-Forwarded-For` (only when the proxy is trusted), or key on an API token or session ID.
- **Single instance only.** This state is in-process. If you run multiple server instances behind a balancer, each enforces the limit independently; for a shared limit you would need an external store such as Redis, or a library like Bucket4j with a distributed backend.

Assumptions: JDK built-in `com.sun.net.httpserver` handler, clients identified by IP address (direct connections, no proxy), limit of 5 requests per sliding one-minute window, rejected requests get `429` with a `Retry-After` header.

```java
import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;

/**
 * Allows each client a fixed number of requests within a sliding time window.
 * Thread-safe. The injected Clock keeps time controllable in tests.
 */
final class SlidingWindowRateLimiter {

    private final int maxRequestsPerWindow;
    private final Duration window;
    private final Clock clock;

    // ubj: entries are never evicted; swap for an expiring cache if client cardinality grows large.
    private final ConcurrentMap<String, Deque<Instant>> requestTimesByClient = new ConcurrentHashMap<>();

    SlidingWindowRateLimiter(int maxRequestsPerWindow, Duration window, Clock clock) {
        if (maxRequestsPerWindow <= 0) {
            throw new IllegalArgumentException("maxRequestsPerWindow must be positive");
        }
        this.maxRequestsPerWindow = maxRequestsPerWindow;
        this.window = window;
        this.clock = clock;
    }

    /** Records a request for the client and reports whether it is within the limit. */
    boolean tryAcquire(String clientId) {
        Deque<Instant> requestTimes =
                requestTimesByClient.computeIfAbsent(clientId, id -> new ArrayDeque<>());
        synchronized (requestTimes) {
            pruneExpired(requestTimes);
            if (requestTimes.size() >= maxRequestsPerWindow) {
                return false;
            }
            requestTimes.addLast(clock.instant());
            return true;
        }
    }

    /** Seconds until the client's oldest recorded request leaves the window; 0 if not limited. */
    long retryAfterSeconds(String clientId) {
        Deque<Instant> requestTimes = requestTimesByClient.get(clientId);
        if (requestTimes == null) {
            return 0;
        }
        synchronized (requestTimes) {
            pruneExpired(requestTimes);
            if (requestTimes.size() < maxRequestsPerWindow) {
                return 0;
            }
            Instant oldestExpiry = requestTimes.peekFirst().plus(window);
            return Math.max(1, Duration.between(clock.instant(), oldestExpiry).toSeconds());
        }
    }

    private void pruneExpired(Deque<Instant> requestTimes) {
        Instant cutoff = clock.instant().minus(window);
        while (!requestTimes.isEmpty() && requestTimes.peekFirst().isBefore(cutoff)) {
            requestTimes.removeFirst();
        }
    }
}
